def compare_versions(a: str, b: str) -> int:
    def parse(v):
        v = v.strip()
        if '+' in v:
            v = v.split('+', 1)[0]
        pre = None
        if '-' in v:
            v, pre_str = v.split('-', 1)
            pre = pre_str.split('.')
        core = [int(x) for x in v.split('.')]
        while len(core) < 3:
            core.append(0)
        return core, pre

    def cmp(x, y):
        return (x > y) - (x < y)

    ca, pa = parse(a)
    cb, pb = parse(b)

    c = cmp(ca, cb)
    if c != 0:
        return c

    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for ia, ib in zip(pa, pb):
        a_num = ia.isdigit()
        b_num = ib.isdigit()
        if a_num and b_num:
            c = cmp(int(ia), int(ib))
        elif a_num:
            c = -1
        elif b_num:
            c = 1
        else:
            c = cmp(ia, ib)
        if c != 0:
            return c

    return cmp(len(pa), len(pb))
